def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        base = 18.0 if no_water_days > 0 or hp <= 3 else 8.0
        return float(min(budget, base))

    prev_bids = []
    prev_need_bids = []
    aggressive_count = 0
    rich_count = 0
    desperate_count = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) >= 400:
            rich_count += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 90:
                    aggressive_count += 1
                opp_req = opp.get('water_requirement', WATER_REQ)
                if opp_req > 0:
                    prev_need_bids.append(float(bid) / float(opp_req))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_need_pressure = max(prev_need_bids) if prev_need_bids else 0.0

    supply_ratio = float(supply) / float(MAX_SUPPLY)
    tight_supply = supply <= 18
    very_tight_supply = supply <= 16

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if very_tight_supply:
        urgency += 2
    elif tight_supply:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1

    if urgency >= 7:
        bid = max(95.0, highest_prev + 3.0)
    elif urgency >= 5:
        bid = max(72.0, avg_prev * 0.9, highest_prev + 1.5 if highest_prev > 0 else 72.0)
    elif urgency >= 3:
        if aggressive_count >= 2 and hp > 4 and no_water_days == 0 and supply >= 20:
            bid = 28.0
        else:
            bid = max(48.0, avg_prev * 0.7, max_need_pressure * WATER_REQ * 0.92)
    else:
        if aggressive_count >= 1 or rich_count >= 2:
            bid = 20.0 if supply_ratio >= 0.8 else 26.0
        else:
            bid = max(18.0, avg_prev * 0.45)

    if day >= 8:
        bid += 8.0
    elif day >= 6 and (hp <= 4 or no_water_days >= 1):
        bid += 5.0

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if days_left >= 3 and hp > 3 and no_water_days == 0:
        reserve_floor = min(budget * 0.45, days_left * 18.0)

    affordable = max(0.0, budget - reserve_floor)
    if urgency >= 5:
        affordable = budget

    bid = min(bid, affordable if affordable > 0 else budget)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate aggressiveness from yesterday
    aggressiveness = 0.0
    if yesterday_bids:
        max_bid_prev = max(yesterday_bids)
        avg_bid_prev = sum(yesterday_bids) / float(len(yesterday_bids))
        # Normalize: heavy if close to cap-ish region
        aggressiveness = 0.6 * (max_bid_prev / 150.0) + 0.4 * (avg_bid_prev / 150.0)

    # Supply factor: when supply is higher, winning water is easier; bid less.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    supply_factor = 1.0
    if supply >= supply_mid:
        supply_factor = 0.85
    else:
        supply_factor = 1.05

    # Urgency: if we've had no water days or low hp, bid higher.
    urgency = 1.0
    if my_hp <= 2.5:
        urgency = 1.35
    elif my_hp <= 4.5:
        urgency = 1.15

    if my_no_water_days >= 2:
        urgency *= 1.15

    # Target bid: aim slightly below aggressive ceiling when hp is ok.
    # Use aggressiveness to set a baseline.
    baseline = DAILY_SALARY * (0.45 + 0.35 * aggressiveness)  # roughly 40-76 when aggressiveness 0-1

    # If yesterday had a very high bid, try to undercut it while still being competitive.
    if yesterday_bids:
        max_bid_prev = max(yesterday_bids)
        if max_bid_prev >= DAILY_SALARY * 0.85:
            target = max_bid_prev * 0.92
        else:
            target = baseline
    else:
        target = baseline

    target *= supply_factor * urgency

    # Ensure we can afford it and keep within reasonable bounds.
    # Also, if budget is scarce, bid proportionally.
    if my_budget <= 0:
        return 0.0

    # Cap bid to avoid bankruptcy when not critical.
    critical = (my_hp <= 3.5) or (my_no_water_days >= 2)
    if critical:
        cap = min(my_budget, DAILY_SALARY * 0.95)
    else:
        cap = min(my_budget, DAILY_SALARY * 0.65)

    bid = float(min(cap, max(0.0, target)))

    # If bid is too low relative to our need, bump modestly.
    # (We don't know exact allocation rule; this is a safe competitiveness nudge.)
    if bid < DAILY_SALARY * 0.35 and critical:
        bid = float(min(my_budget, DAILY_SALARY * 0.55))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday's bids
    prev_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # Determine baseline from yesterday's competition
    if prev_bids:
        highest_prev = max(prev_bids)
    else:
        highest_prev = 0.0

    # Adjust based on supply
    supply = day_context['supply']
    supply_factor = 1.0
    if supply < 20:
        supply_factor = 1.3
    else:
        supply_factor = 0.9

    # Adjust based on our hp
    hp = my_status['hp']
    if hp <= 2:
        # critical: bid high to ensure water
        bid_target = DAILY_SALARY * 0.95
    elif hp <= 5:
        # moderate risk: bid to beat highest_prev if needed
        if highest_prev >= DAILY_SALARY * 0.85:
            bid_target = highest_prev + 1.5
        else:
            bid_target = max(DAILY_SALARY * 0.6, highest_prev + 1.0)
    else:
        # healthy: can be conservative
        if highest_prev >= DAILY_SALARY * 0.85:
            bid_target = DAILY_SALARY * 0.35
        else:
            bid_target = max(DAILY_SALARY * 0.4, highest_prev + 0.5)

    # Apply supply factor and cap by budget
    bid = bid_target * supply_factor
    bid = min(bid, my_status['budget'])
    bid = max(bid, 1.0)  # always bid at least 1
    return bid
